{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let d = [];

  try {
    await page.evaluateOnNewDocument(() => {
      Object.defineProperty(navigator, 'webdriver', { get: () => false });
      window.chrome = { runtime: {} };
    });
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');
    await page.setViewport({ width: 1280, height: 800 });

    // LOGIN - vai direto para a pagina do produto (mostra login se nao logado)
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'networkidle2', timeout: 20000 });
    await w(2000);
    d.push('P');

    // Verifica se precisa logar
    const needsLogin = await page.evaluate(() => {
      return !!document.querySelector('#email_principal') || document.body.innerText.includes('Digite seu Email');
    });

    if (needsLogin) {
      d.push('NL');

      // EMAIL
      const eInp = await page.$('#email_principal');
      if (eInp) { await eInp.type(EMAIL, { delay: 10 }); }
      await w(300);

      // CONTINUAR
      await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email')); if(b) b.click(); });
      await w(2000);

      // SENHA
      const pwd = await page.$('#pwdInput');
      if (pwd) { await pwd.type(SENHA, { delay: 10 }); d.push('S'); }
      await w(300);

      // ENTRAR
      await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar'); if(b) b.click(); });
      d.push('E');

      // ESPERA LOGIN COMPLETAR - verifica se Hapvida aparece
      for (let i = 0; i < 10; i++) {
        await w(1000);
        const hasHapvida = await page.evaluate(() => !!document.querySelector('img[src*="hapvida"]'));
        if (hasHapvida) {
          d.push('H' + i);
          break;
        }
      }
    } else {
      d.push('AL'); // Already logged in
    }

    // CLICA NO HAPVIDA (na pagina de selecao de operadora)
    const hapClicked = await page.evaluate(() => {
      const img = document.querySelector('img[src*="hapvida"]');
      if (img) {
        const parent = img.closest('.clickable-element') || img.parentElement.parentElement;
        if (parent) { parent.click(); return true; }
      }
      return false;
    });
    if (hapClicked) { d.push('HC'); } else { d.push('HC:no'); }
    await w(2000);

    // AGORA VERIFICA SE ESTA NA PAGINA DO FORM
    const pageState = await page.evaluate(() => {
      const hasPME = [...document.querySelectorAll('.clickable-element')].some(e => e.textContent.includes('PME') && e.textContent.includes('29'));
      const hasNome = !!document.querySelector('#id-nomelead');
      const text = document.body.innerText.substring(0, 300);
      return { hasPME, hasNome, text: text.substring(0, 150) };
    });

    d.push('PME:' + pageState.hasPME);

    if (!pageState.hasPME) {
      return { success: false, debug: d.join('-'), pageState, message: 'PME not found after login' };
    }

    // PME
    await page.evaluate(() => { const p = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29')); if(p) p.click(); });
    await w(1000);
    d.push('M');

    // NOME
    const nInp = await page.$('#id-nomelead');
    if (nInp) { await nInp.type('teste', { delay: 5 }); d.push('N'); }
    await w(300);

    // AVANCAR 1
    await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.includes('Avan') && s.display !== 'none' && s.visibility !== 'hidden') { b.click(); break; } } });
    await w(1500);
    d.push('1');

    // Verifica se avancou
    const step2 = await page.evaluate(() => !!document.querySelector('#cidade_nome'));
    d.push('S2:' + step2);

    return { success: true, debug: d.join('-'), pageState };
  } catch (error) {
    return { success: false, error: error.message, debug: d.join('-') };
  }
}"
}
